use vstd::prelude::*;

verus! {

    // Specification: membership in Set A
    spec fn is_set_a(c: char) -> bool {
        c == 'A' || c == 'E' || c == 'F' || c == 'H' || c == 'I'
     || c == 'K' || c == 'L' || c == 'M' || c == 'N' || c == 'T'
     || c == 'V' || c == 'W' || c == 'X' || c == 'Y' || c == 'Z'
    }

    // Specification: membership in Set B
    spec fn is_set_b(c: char) -> bool {
        c == 'B' || c == 'C' || c == 'D' || c == 'G' || c == 'J'
     || c == 'O' || c == 'P' || c == 'Q' || c == 'R' || c == 'S'
     || c == 'U'
    }

    // All characters of word are in Set A
    spec fn all_in_set_a(word: &Vec<char>) -> bool {
        forall |i: int|
            0 <= i && i < (word.len() as int)
            ==> is_set_a(word[i as usize])
    }

    // All characters of word are in Set B
    spec fn all_in_set_b(word: &Vec<char>) -> bool {
        forall |i: int|
            0 <= i && i < (word.len() as int)
            ==> is_set_b(word[i as usize])
    }

    // Word is entirely in one set
    spec fn all_same_set(word: &Vec<char>) -> bool {
        all_in_set_a(word) || all_in_set_b(word)
    }

    // solve: returns "YES" if all chars are in A or all in B, else "NO"
    fn solve(word: Vec<char>) -> (result: Vec<char>)
        requires
            1 <= word.len() && word.len() <= 10
            && forall |i: int|
                0 <= i && i < (word.len() as int)
                ==>
                    let c = word[i as usize];
                    c >= 'A' && c <= 'Z'
        ensures
            // If all chars in one set, return ['Y','E','S'], otherwise ['N','O']
            (all_same_set(&word) && result == vec!['Y','E','S'])
         || (!all_same_set(&word) && result == vec!['N','O'])
    {
        // We'll track two flags:
        // all_a == true  means so far all processed chars were in Set A
        // all_b == true  means so far all processed chars were in Set B
        let mut all_a: bool = true;
        let mut all_b: bool = true;
        let mut i: usize = 0;
        while i < word.len()
            invariant i <= word.len()
            invariant
                // if all_a is still true then every index < i is in Set A
                (all_a ==>
                    forall |j: int|
                        0 <= j && j < (i as int)
                        ==> is_set_a(word[j as usize]))
            invariant
                // if all_b is still true then every index < i is in Set B
                (all_b ==>
                    forall |j: int|
                        0 <= j && j < (i as int)
                        ==> is_set_b(word[j as usize]))
            decreases word.len() - i
        {
            let c: char = word[i];
            if !is_set_a(c) {
                all_a = false;
            }
            if !is_set_b(c) {
                all_b = false;
            }
            i = i + 1;
        }
        // At this point:
        // all_a ==> all_in_set_a(&word)
        // all_b ==> all_in_set_b(&word)
        // hence (all_a || all_b) <==> all_same_set(&word)
        if all_a || all_b {
            vec!['Y','E','S']
        } else {
            vec!['N','O']
        }
    }
}

